using System;using LoopFive;
class CleanupTests{
 static double Tone(float hz,SessionConfig c){MicCleaner f=new MicCleaner();f.Configure(c);double sum=0;for(int i=0;i<88200;i++){float l=(float)Math.Sin(2*Math.PI*hz*i/44100)*.2f,r=l;f.Tick(ref l,ref r);if(i>44100)sum+=l*l;}return Math.Sqrt(sum/44099);}
 static void Check(bool ok,string name){if(!ok)throw new Exception(name);Console.WriteLine("PASS "+name);}
 static void Main(){SessionConfig c=new SessionConfig();MicCleaner f=new MicCleaner();f.Configure(c);float l=.123f,r=-.456f;f.Tick(ref l,ref r);Check(l==.123f&&r==-.456f,"bypass preserves exact stereo samples");c.MicCleanup=true;c.MicHighPass=100;c.MicLowPass=0;c.MicNoiseThreshold=0;Check(Tone(20,c)<Tone(1000,c)*.06,"air rumble attenuated while voice band retained");c.MicHighPass=0;c.MicLowPass=5000;Check(Tone(16000,c)<Tone(1000,c)*.45,"high frequency hiss filtering");c.MicLowPass=0;c.MicNoiseThreshold=.01f;c.MicReductionDb=24;f=new MicCleaner();f.Configure(c);for(int i=0;i<88200;i++){l=.001f;r=-.001f;f.Tick(ref l,ref r);}Check(l<.00007f&&l>0&&Math.Abs(l+r)<1e-8,"background reduced smoothly with linked stereo");for(int i=0;i<441;i++){l=.2f;r=-.2f;f.Tick(ref l,ref r);}Check(l>.19f,"fast opening retains wanted sounds");c.MicCleanup=false;f.Configure(c);l=.001f;r=.002f;f.Tick(ref l,ref r);Check(l==.001f&&r==.002f,"disable restores original signal immediately");Console.WriteLine("6 cleanup checks passed");}
}
